<template>
  <v-card
    class="mx-auto ma-0 pa-0"
    max-width="400"
  >
    <v-container v-bind:class="(editMode) ? 'edit-mode ma-0 pa-0' : 'view-mode ma-0 pa-0'" fluid>
      <div class="presetHeader">
        <div class="instrumentImage">
          <v-img class="instrumentIconImage" :src="imageURL" contain @click="onIconClick()"/>
        </div>
        <div class="saveSongPreset()">
          <v-icon
            v-if="editMode"
            class="mr-2 ma-0 pa-0"
            @click="saveSongPreset()"
          >
          save
          </v-icon>
        </div>
        <div class="presetName"
          v-bind:class="(volume > 0) ? 'active' : 'inactive'"
          @click="onPresetClick()">
          <b>{{ getPresetName() }}</b>
        </div>
      </div>

      <v-row no-gutters>
        <div class="volumeControl">
          <button
            v-if="editMode"
            type="button"
            class="volumeStepButton"
            :disabled="volume <= 0"
            aria-label="Decrease volume by 5"
            @click="adjustVolume(-5)"
          >&lt;&lt;</button>
          <div class="customKnob">
            <my-knob
              v-model='volume'
              :editMode='editMode'
              :activeVolumePedal='activeVolumePedal'
              knobLabel='Vol'
              :base-color='getBaseColor()'
              @doubleclick="onVolumeKnobDoubleClick()"
            />
          </div>
          <button
            v-if="editMode"
            type="button"
            class="volumeStepButton"
            :disabled="volume >= 127"
            aria-label="Increase volume by 5"
            @click="adjustVolume(5)"
          >&gt;&gt;</button>
        </div>
        <div class="customKnob">
          <my-knob
            v-model='pan'
            :editMode='editMode'
            knobLabel='Pan'
            :base-color='getBaseColor()'
            @doubleclick="onPanKnobDoubleClick()"
          />
        </div>
        <div
          v-if="volume > 0"
          class="effectToggleGrid"
        >
          <v-checkbox
            :readonly="!editMode"
            class="ma-0 pa-0 checkbox"
            dense hide-details
            label="Boost"
            :disabled="volume == 0"
            v-model="songPreset.boostflag" />
          <v-checkbox
            :readonly="!editMode"
            class="ma-0 pa-0 checkbox"
            dense hide-details
            label="Rev"
            :disabled="volume == 0"
            v-model="songPreset.reverbflag" />
          <v-checkbox
            :readonly="!editMode"
            class="ma-0 pa-0 checkbox"
            dense hide-details
            label="Del"
            :disabled="volume == 0"
            v-model="songPreset.delayflag" />
          <v-checkbox
            :readonly="!editMode"
            class="ma-0 pa-0 checkbox"
            dense hide-details
            label="Mod"
            :disabled="volume == 0"
            v-model="songPreset.modeflag" />
        </div>
          <v-dialog v-if="editMode"  v-model="dialog" persistent max-width="600px">
            <v-card>
              <v-card-title class="headline">Preset</v-card-title>
              <v-card-text>
                <v-select
                  class="mx-0"
                  :items="presets"
                  v-model="presetId"
                  label="Preset"
                  required
                  item-text="name"
                  item-value="id">
                </v-select>
                <div v-if="selectedPreset" class="actualPresetInfo">
                  <div class="caption">Actual app preset:</div>
                  <div>{{ selectedPresetInstrumentName }} / PC {{ selectedPreset.midipc }}</div>
                </div>
              </v-card-text>

              <v-card-actions>
                <v-spacer></v-spacer>
                <v-btn
                  color="green darken-1"
                  text
                  @click="dialog = false"
                >
                  Cancel
                </v-btn>

                <v-btn
                  color="green darken-1"
                  text
                  :disabled="!selectedPreset"
                  @click="showPresetUsage()"
                >
                  <v-icon left small>format_list_bulleted</v-icon>
                  Used In
                </v-btn>

                <v-btn
                  color="green darken-1"
                  text
                  @click="setPreset()"
                >
                  OK
                </v-btn>
              </v-card-actions>
            </v-card>
          </v-dialog>
          <v-dialog v-if="editMode" v-model="usageDialog" max-width="760px">
            <v-card>
              <v-card-title class="headline">
                <v-icon left>format_list_bulleted</v-icon>
                Preset Usage
              </v-card-title>
              <v-card-text>
                <div v-if="selectedPreset" class="mb-3">
                  <div><b>{{ selectedPreset.name }}</b></div>
                  <div class="caption">Actual app preset: {{ selectedPresetInstrumentName }} / PC {{ selectedPreset.midipc }}</div>
                </div>

                <v-progress-linear v-if="usageLoading" indeterminate color="green darken-1" />

                <v-alert v-else-if="usageError" type="error" dense text>
                  Could not load preset usage.
                </v-alert>

                <v-alert v-else-if="presetUsage && presetUsage.usageCount === 0" type="info" dense text>
                  This actual app preset is not used in any song program.
                </v-alert>

                <v-simple-table v-else-if="presetUsage">
                  <thead>
                    <tr>
                      <th>Song</th>
                      <th>Program</th>
                      <th>Preset</th>
                      <th class="text-right">Volume</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="usage in presetUsage.usages" :key="`${usage.songId}-${usage.programId}-${usage.songPresetId}`">
                      <td>{{ usage.songName }}</td>
                      <td>{{ usage.programName }}</td>
                      <td>{{ usage.presetName }}</td>
                      <td class="text-right">{{ usage.volume }}</td>
                    </tr>
                  </tbody>
                </v-simple-table>
              </v-card-text>
              <v-card-actions>
                <v-spacer></v-spacer>
                <v-btn color="green darken-1" text @click="usageDialog = false">
                  Close
                </v-btn>
              </v-card-actions>
            </v-card>
          </v-dialog>
      </v-row>
    </v-container>
  </v-card>
</template>

<script>
import { mapState } from 'vuex'
import _sortBy from 'lodash/sortBy'
import PresetUsageService from '@/services/PresetUsageService'

export default {
  props: {
    presetControlData: {
      type: Object
    },
    activeVolumePedal: {
      type: Boolean,
      default: false
    },
    programIdx: {
      type: Number,
      default: -1
    }
  },
  data () {
    return {
      editMode: false,
      dialog: false,
      usageDialog: false,
      usageLoading: false,
      usageError: false,
      presetUsage: null,

      imageURL: '',
      presets: {},
      presetId: -1,
      midichannel: 0,

      songPreset: {
        id: -1,
        refsong: -1,
        refsongprogram: -1,
        refinstrument: -1,
        refinstrumentbank: -1,
        refpreset: -1,
        volume: 0,
        pan: 0,
        muteflag: 0,
        boostflag: 0,
        reverbflag: 0,
        delayflag: 0,
        modeflag: 0,
        reverbvalue: 0,
        delayvalue: 0
      }
    }
  },
  // created () {
  //   Object.assign(this.songPreset, this.presetControlData)
  // },

  computed: {
    ...mapState(['presetList', 'instrumentList', 'instrumentBankList', 'songList', 'presetVolumeFromController']),

    volume: {
      get () {
        // console.log(this.songPreset.volume)
        return this.songPreset.volume
      },
      set (val) {
        this.setVolume(val)
      }
    },
    pan: {
      get () {
        if (this.songPreset && this.songPreset.volume > 0) return this.songPreset.pan
        else return 0
      },
      set (val) {
        this.songPreset.pan = val
      }
    },
    selectedPreset () {
      if (!this.presetList || this.presetId < 0) return null
      return this.presetList.find(item => item.id === this.presetId)
    },
    selectedPresetInstrumentName () {
      if (!this.selectedPreset || !this.instrumentList) return ''
      const instrument = this.instrumentList.find(item => item.id === this.selectedPreset.refinstrument)
      if (!instrument) return `Instrument ${this.selectedPreset.refinstrument}`
      return instrument.name
    }
  },

  watch: {
    presetControlData: function () {
      if (this.presetControlData && this.presetControlData.id > -1) {
        Object.assign(this.songPreset, this.getDefaultSongPreset(), this.presetControlData)
        if (typeof this.songPreset !== 'undefined' && this.songPreset.refpreset > -1) {
          if (typeof this.instrumentList !== 'undefined' && this.instrumentList &&
            this.songPreset.refinstrument > 0) {
            const instrument = this.instrumentList.find(item => item.id === this.songPreset.refinstrument)
            if (instrument) {
              this.imageURL = instrument.imageURL
              this.midichannel = instrument.midichannel
              this.populatePresetList(this.songPreset.refinstrument)
            } else {
              this.imageURL = ''
              this.midichannel = 0
            }
          }
        } else {
          this.$log.debug('------------- empty -----')
          // this.$log.debug(this.songPreset)
        }
      }
    },
    presetVolumeFromController: function () {
      // this.$log.debug('--> presetControl-----')
      // this.$log.debug(this.presetVolumeFromController)
      if (this.editMode) {
        this.setVolume(this.presetVolumeFromController)
      }
    }
  },

  methods: {
    setVolume (val) {
      this.songPreset.volume = val
      // if (this.editMode) {
      // const payload = {
      // 'songId': this.songPreset.refsong,
      // 'programIdx': this.programIdx,
      // 'presetId': this.songPreset.refpreset,
      // 'instrumentId': this.songPreset.refinstrument,
      // 'value': val
      // }
      // console.log(this.songPreset)
      // this.$store.dispatch('sendChangePresetVolumeMessage', payload)
      // }
    },

    adjustVolume (step) {
      if (!this.editMode) return
      const currentVolume = Number(this.songPreset.volume) || 0
      this.setVolume(Math.max(0, Math.min(127, currentVolume + step)))
    },

    getDefaultSongPreset () {
      return {
        id: -1,
        refsong: -1,
        refsongprogram: -1,
        refinstrument: -1,
        refinstrumentbank: -1,
        refpreset: -1,
        volume: 0,
        pan: 0,
        muteflag: 0,
        boostflag: 0,
        reverbflag: 0,
        delayflag: 0,
        modeflag: 0,
        reverbvalue: 0,
        delayvalue: 0
      }
    },

    resetUsageState () {
      this.usageDialog = false
      this.usageLoading = false
      this.usageError = false
      this.presetUsage = null
    },

    async showPresetUsage () {
      if (!this.selectedPreset) return

      this.usageDialog = true
      this.usageLoading = true
      this.usageError = false
      this.presetUsage = null

      try {
        this.presetUsage = await PresetUsageService.getUsage(
          this.selectedPreset.refinstrument,
          this.selectedPreset.midipc
        )
      } catch (ex) {
        this.usageError = true
        this.$log.error(ex)
      } finally {
        this.usageLoading = false
      }
    },

    setEditMode (value) {
      let channel = 0
      if (value) {
        channel = this.midichannel
      }
      this.editMode = value
      this.$store.dispatch('sendEditMode', channel)
    },

    getPresetName () {
      if (typeof this.presetList === 'undefined' || this.presetList === null ||
        typeof this.songPreset === 'undefined' || this.songPreset === null ||
        typeof this.instrumentList === 'undefined' || this.instrumentList === null) {
        return {}
      }
      const pr = this.presetList.find(item => item.id === this.songPreset.refpreset)
      if (typeof pr === 'undefined') {
        return {}
      }
      // this.$log.debug(pr.name)
      return pr.name
    },

    async populatePresetList (id) {
      if (typeof this.presetList !== 'undefined' && this.presetList !== null &&
        typeof this.songPreset !== 'undefined' && this.songPreset !== null) {
        // this.$log.debug('---get--preset--------------')
        const list = this.presetList.filter(item => item.refinstrument === id)
        this.presets = _sortBy(list, 'name')
        // this.$log.debug(this.presets)
      }
    },
    setPreset () {
      const preset = this.presetList.find(item => item.id === this.presetId)
      // this.$log.debug('---set-preset---------------')
      // this.$log.debug(preset)
      if (preset) {
        this.songPreset.refpreset = this.presetId
        this.songPreset.refinstrumentbank = preset.refinstrumentbank
        this.songPreset.refinstrument = preset.refinstrument
        if (Number(preset.midipc) === 0) {
          this.songPreset.volume = 0
          this.songPreset.pan = 64
        }

        this.dialog = false
        this.resetUsageState()
      }
    },
    saveSongPreset () {
      // this.$log.debug(this.songPreset)
      this.$store.dispatch('updateSongProgramPreset', this.songPreset)
      this.setEditMode(false)
      this.$emit('changed', true)
    },
    onIconClick () {
      this.setEditMode(!this.editMode)
      this.presetId = this.songPreset.refpreset
      this.resetUsageState()
    },
    onPresetClick () {
      if (this.editMode) {
        // this.$log.debug(this.presets)
        this.resetUsageState()
        this.dialog = true
      }
    },
    getBaseColor () {
      if (this.songPreset && this.songPreset.volume > 0) return 'snow'
      else return 'gray'
    },
    onVolumeKnobDoubleClick (item) {
      if (this.editMode) {
        this.volume = 0
      }
      // console.log('%%%% Knob click')
    },
    onPanKnobDoubleClick (item) {
      if (this.editMode) {
        this.pan = 0
      }
      // console.log('%%%% Knob click')
    }
  }
}
</script>

